import type { DatabaseSync, SQLInputValue } from 'node:sqlite';
import { randomUUID } from 'node:crypto';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Attempts allowed in total before a job is marked failed. */
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  run_after: number | null;
  created_at: string;
  updated_at: string;
}

export interface JobJson {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJobJson(row: JobRow): JobJson {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function one<T>(db: DatabaseSync, sql: string, ...params: SQLInputValue[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

function now(): string {
  return new Date().toISOString();
}

export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

/**
 * Creates a job, or replays/rejects an earlier submission with the same idempotency key. The whole
 * check-and-insert runs in one immediate transaction, so a key can never create two jobs.
 */
export function createJob(
  db: DatabaseSync,
  value: NewJob,
  key: string | undefined,
): { kind: 'created' | 'replay'; row: JobRow } | { kind: 'conflict' } {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = one<{ job_id: string }>(db, 'SELECT job_id FROM idempotency_keys WHERE key = ?', key);
      if (existing) {
        const row = getJob(db, existing.job_id)!;
        db.exec('COMMIT');
        const same = row.input === value.input && row.steps === value.steps && row.fail_attempts === value.failAttempts;
        return same ? { kind: 'replay', row } : { kind: 'conflict' };
      }
    }
    const ts = now();
    const row = one<JobRow>(
      db,
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?) RETURNING *`,
      randomUUID(),
      value.input,
      value.steps,
      value.failAttempts,
      ts,
      ts,
    )!;
    if (key !== undefined) db.prepare('INSERT INTO idempotency_keys (key, job_id) VALUES (?, ?)').run(key, row.id);
    db.exec('COMMIT');
    return { kind: 'created', row };
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open
    }
    throw e;
  }
}

/** Atomically takes the oldest queued job that is due, and starts a new attempt on it. */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return one<JobRow>(
    db,
    `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, run_after = NULL, updated_at = ?
     WHERE seq = (
       SELECT seq FROM jobs
       WHERE status = 'queued' AND (run_after IS NULL OR run_after <= ?)
       ORDER BY seq LIMIT 1
     )
     RETURNING *`,
    now(),
    nowMs,
  );
}

export function recordProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(completed, now(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', output = ?, completed = steps, error = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(output, now(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(error, now(), id);
}

export function scheduleRetry(db: DatabaseSync, id: string, runAfterMs: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(runAfterMs, now(), id);
}

/**
 * Returns a running job to the queue without counting the interrupted attempt, which never
 * reported an outcome. Used on graceful shutdown and when a restarted worker finds jobs left running.
 */
export function releaseJob(db: DatabaseSync, id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, attempts = MAX(attempts - 1, 0), run_after = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(now(), id);
}

export function releaseAllRunning(db: DatabaseSync): number {
  const result = db
    .prepare(
      `UPDATE jobs SET status = 'queued', completed = 0, attempts = MAX(attempts - 1, 0), run_after = NULL, updated_at = ?
       WHERE status = 'running'`,
    )
    .run(now());
  return Number(result.changes);
}

export function beat(db: DatabaseSync, name: string, nowMs: number): void {
  db.prepare(
    'INSERT INTO heartbeats (name, at) VALUES (?, ?) ON CONFLICT (name) DO UPDATE SET at = excluded.at',
  ).run(name, nowMs);
}

export function lastBeat(db: DatabaseSync, name: string): number | undefined {
  return one<{ at: number }>(db, 'SELECT at FROM heartbeats WHERE name = ?', name)?.at;
}

