import type { NewJob } from './store.ts';

export interface FieldError {
  field: string;
  message: string;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const MAX_INPUT_LENGTH = 1000;

function isIntegerInRange(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Validates a parsed submission body and applies defaults. Collects every offending field. */
export function validateSubmission(body: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Body must be a JSON object.' }] };
  }
  const record = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const input = record.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters.` });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }

  const steps = record.steps ?? 5;
  if (!isIntegerInRange(steps, 1, 20)) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });

  const failAttempts = record.failAttempts ?? 0;
  if (!isIntegerInRange(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

