import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import * as store from './store.ts';
import { validateSubmission, type FieldError } from './validation.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_FRESH_MS = 3000;

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'No such route.');
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this route.', undefined);
  res.setHeader('allow', allow);
}

function readBody(req: IncomingMessage): Promise<{ tooLarge: boolean; text: string }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    });
    req.on('end', () => resolve({ tooLarge: size > MAX_BODY_BYTES, text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

async function createJobHandler(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  let key: string | undefined;
  const rawKey = req.headers['idempotency-key'];
  if (rawKey !== undefined) {
    if (typeof rawKey === 'string' && IDEMPOTENCY_KEY_PATTERN.test(rawKey)) key = rawKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let parsed: unknown;
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else {
    const { tooLarge, text } = await readBody(req);
    if (tooLarge) {
      fields.push({ field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` });
    } else {
      try {
        parsed = JSON.parse(text);
      } catch {
        fields.push({ field: 'body', message: 'Body must be valid JSON.' });
      }
    }
  }

  if (fields.length === 0) {
    const validation = validateSubmission(parsed);
    if (!validation.ok) fields.push(...validation.fields);
    else {
      const result = store.createJob(db, validation.value, key);
      if (result.kind === 'conflict') {
        return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      }
      return send(res, result.kind === 'created' ? 201 : 200, store.toJobJson(result.row));
    }
  }
  sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
}

function handle(req: IncomingMessage, res: ServerResponse): Promise<void> | void {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const at = store.lastBeat(db, 'worker');
    const up = at !== undefined && Date.now() - at <= WORKER_FRESH_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      return send(res, 200, { jobs: store.listJobs(db).map(store.toJobJson) });
    }
    if (method === 'POST') return createJobHandler(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const row = store.getJob(db, decodeURIComponent(match[1]!));
    if (!row) return notFound(res);
    return send(res, 200, store.toJobJson(row));
  }
  notFound(res);
}

const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => handle(req, res))
    .catch((err: unknown) => {
      console.error('request failed:', err);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
process.on('SIGTERM', () => {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
});

