import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import * as store from './store.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2000;
const WORKER_NAME = 'worker';

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function beat(): void {
  try {
    store.beat(db, WORKER_NAME, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

// A worker that starts after a crash finds jobs still marked running; they are processed again.
const released = store.releaseAllRunning(db);
if (released > 0) console.log(`requeued ${released} interrupted job(s)`);
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

function retryDelayMs(): number {
  return RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS + 1));
}

async function runAttempt(job: store.JobRow): Promise<void> {
  // job.attempts already counts this attempt (attempt n of the job).
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return store.releaseJob(db, job.id);
    if (job.attempts < store.MAX_ATTEMPTS) store.scheduleRetry(db, job.id, Date.now() + retryDelayMs());
    else store.failJob(db, job.id, store.TRANSIENT_ERROR);
    return;
  }

  for (let done = 1; done <= job.steps; done++) {
    await sleep(STEP_MS);
    if (stopping) return store.releaseJob(db, job.id);
    store.recordProgress(db, job.id, done);
  }
  store.completeJob(db, job.id, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  try {
    const job = store.claimNextJob(db, Date.now());
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (err) {
    console.error('worker iteration failed:', err);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
try {
  store.releaseAllRunning(db);
} catch {
  // leave any running job for the next start to recover
}
db.close();
console.log('worker stopped');
process.exit(0);

