  return RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS + 1));
}

async function runAttempt(job: store.JobRow): Promise<void> {
  // job.attempts already counts this attempt (attempt n of the job).
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return store.releaseJob(db, job.id);
    if (job.attempts < store.MAX_ATTEMPTS) store.scheduleRetry(db, job.id, Date.now() + retryDelayMs());
    else store.failJob(db, job.id, store.TRANSIENT_ERROR);
    return;
  }

  for (let done = 1; done <= job.steps; done++) {
    await sleep(STEP_MS);
    if (stopping) return store.releaseJob(db, job.id);
    store.recordProgress(db, job.id, done);
  }
  store.completeJob(db, job.id, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  try {
    const job = store.claimNextJob(db, Date.now());
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (err) {
    console.error('worker iteration failed:', err);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
try {
  store.releaseAllRunning(db);
} catch {
  // leave any running job for the next start to recover
}
db.close();
console.log('worker stopped');
process.exit(0);

