mkdir -p "$TMPDIR/jt" && cat > "$TMPDIR/jt/e2e.mjs" <<'EOF'
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
const ROOT = process.argv[2];
const DB = process.argv[3];
const PORT = 3917;
const base = `http://127.0.0.1:${PORT}`;
let fails = 0;
const ok = (c, m) => { console.log(c ? 'ok  ' : 'FAIL', m); if (!c) fails++; };
const procs = {};
function start(name) {
  procs[name] = spawn('node', [`${ROOT}/dist/${name}.js`], { env: { ...process.env, PORT: String(PORT), DATABASE_PATH: DB }, stdio: ['ignore', 'inherit', 'inherit'] });
}
async function req(method, path, body, headers = {}) {
  const r = await fetch(base + path, { method, headers: { 'content-type': 'application/json', ...headers }, body: body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body)) });
  const text = await r.text(); let json; try { json = JSON.parse(text) } catch {}
  return { status: r.status, json, ct: r.headers.get('content-type'), headers: r.headers };
}
async function waitFinal(id, ms = 15000) {
  const end = Date.now() + ms;
  while (Date.now() < end) { const j = (await req('GET', `/api/jobs/${id}`)).json; if (j.status === 'completed' || j.status === 'failed') return j; await sleep(100); }
  throw new Error('timeout ' + id);
}
async function wait(pred, ms = 15000) { const end = Date.now() + ms; while (Date.now() < end) { if (await pred()) return true; await sleep(100); } return false; }

start('server'); start('worker');
await wait(async () => (await req('GET', '/health').catch(() => null))?.json?.worker === 'up', 10000);
ok((await req('GET', '/health')).json.worker === 'up', 'health reports worker up');

// failure after 3 attempts
let r = await req('POST', '/api/jobs', { input: 'boom', steps: 2, failAttempts: 3 });
ok(r.status === 201, 'create failAttempts 3 -> 201');
const failed = await waitFinal(r.json.id);
ok(failed.status === 'failed' && failed.error === 'transient failure' && failed.attempts === 3 && failed.result === null, `failAttempts 3 -> failed after 3 attempts ${JSON.stringify({s:failed.status,a:failed.attempts,e:failed.error})}`);

r = await req('POST', '/api/jobs', { input: 'two fails', failAttempts: 2 });
const two = await waitFinal(r.json.id);
ok(two.status === 'completed' && two.attempts === 3 && two.result.output === 'TWO FAILS', 'failAttempts 2 completes on attempt 3');

// validation
const bad = [
  ['{"input":"a","steps":"3"}', 'steps'], ['{"input":"a","steps":21}', 'steps'], ['{"input":"a","steps":2.5}', 'steps'],
  ['{"input":"a","failAttempts":6}', 'failAttempts'], ['{"input":"   "}', 'input'], ['{"input":""}', 'input'],
  ['{"input":"a","x":1}', 'x'], ['{"input":"a"', 'body'], ['[1]', 'body'], ['"s"', 'body'], ['null', 'body'],
];
for (const [b, f] of bad) {
  const x = await req('POST', '/api/jobs', b);
  ok(x.status === 400 && x.json.error.code === 'invalid_request' && x.json.error.fields.some((e) => e.field === f) && x.ct.startsWith('application/json'), `invalid ${b} -> 400 field ${f}`);
}
r = await req('POST', '/api/jobs', '{"input":"a"}', { 'content-type': 'text/plain' });
ok(r.status === 400 && r.json.error.fields[0].field === 'body', 'text/plain -> 400 body');
r = await req('POST', '/api/jobs', { input: 'a' }, { 'Idempotency-Key': 'bad key!' });
ok(r.status === 400 && r.json.error.fields.some((e) => e.field === 'Idempotency-Key'), 'bad idempotency key -> 400');
r = await req('POST', '/api/jobs', { input: 'a'.repeat(1000) });
ok(r.status === 201, '1000-char input accepted');
r = await req('POST', '/api/jobs', { input: 'a'.repeat(1001) });
ok(r.status === 400, '1001-char input rejected');

// idempotency
r = await req('POST', '/api/jobs', { input: 'idem' }, { 'Idempotency-Key': 'k-1' });
const k1 = r.json.id; ok(r.status === 201, 'idem first -> 201');
r = await req('POST', '/api/jobs', { input: 'idem', steps: 5, failAttempts: 0 }, { 'Idempotency-Key': 'k-1' });
ok(r.status === 200 && r.json.id === k1, 'idem same payload after defaults -> 200 same id');
r = await req('POST', '/api/jobs', { input: 'idem', steps: 4 }, { 'Idempotency-Key': 'k-1' });
ok(r.status === 409 && r.json.error.code === 'idempotency_conflict', 'idem different payload -> 409');

// routing
ok((await req('GET', '/nope')).json.error.code === 'not_found', 'unknown path 404');
r = await req('DELETE', '/api/jobs'); ok(r.status === 405 && r.json.error.code === 'method_not_allowed' && r.headers.get('allow') === 'GET, POST', 'wrong method 405 with Allow');
ok((await req('GET', '/api/jobs/zzz')).status === 404, 'missing job 404');
const html = await fetch(base + '/'); const page = await html.text();
ok(html.status === 200 && html.headers.get('content-type').startsWith('text/html') && page.includes('data-testid="job-list"'), 'GET / serves UI');

// long job for SIGKILL recovery
r = await req('POST', '/api/jobs', { input: 'survive', steps: 20 });
const survivor = r.json.id;
await wait(async () => (await req('GET', `/api/jobs/${survivor}`)).json.status === 'running', 5000);
const mid = (await req('GET', `/api/jobs/${survivor}`)).json;
ok(mid.status === 'running' && mid.progress.completed >= 1 && mid.progress.completed < 20, `running with progress ${mid.progress.completed}/20`);
procs.worker.kill('SIGKILL');
await sleep(3500);
ok((await req('GET', '/health')).json.worker === 'down', 'health down after worker killed');
procs.server.kill('SIGKILL'); await sleep(300);
start('server'); start('worker');
await wait(async () => (await req('GET', '/health').catch(() => null))?.json?.worker === 'up', 10000);
const after = await waitFinal(survivor, 12000);
ok(after.status === 'completed' && after.result.output === 'SURVIVE', 'running job reprocessed after SIGKILL and completed');
const list = (await req('GET', '/api/jobs')).json.jobs;
ok(list.filter((j) => j.input === 'idem').length === 1, 'idempotent job not duplicated across restart');
ok(list.some((j) => j.id === k1) && list.length >= 6, 'jobs persisted across restart');
ok(list[0].id === survivor, 'newest first ordering');

// graceful SIGTERM
const t0 = Date.now();
const wexit = new Promise((res) => procs.worker.once('exit', (c, s) => res([c, s])));
procs.worker.kill('SIGTERM');
const [wc, ws] = await wexit; ok(wc === 0 && Date.now() - t0 < 3000, `worker SIGTERM exit code ${wc} sig ${ws} in ${Date.now() - t0}ms`);
const sexit = new Promise((res) => procs.server.once('exit', (c, s) => res([c, s])));
procs.server.kill('SIGTERM');
const [sc] = await sexit; ok(sc === 0, `server SIGTERM exit code ${sc}`);
console.log(fails === 0 ? 'ALL PASSED' : `${fails} FAILED`);
process.exit(fails ? 1 : 0);
EOF
cd <workspace> && rm -rf "$TMPDIR/jt/db" && node "$TMPDIR/jt/e2e.mjs" "$PWD" "$TMPDIR/jt/db/jobs.db" 2>&1 | grep -v ExperimentalWarning
